const rows = [];
for (let i = 0; i < 30; i++) {
  const date = new Date(Date.UTC(2026, 9, 15 + i)).toISOString().slice(0, 10);
  const metaPurchases = 5 + (i % 3);
  const googlePurchases = 8 + (i % 3);
  rows.push(
    {
      date, channel: 'meta', campaign_id: 'demo-meta-01', currency: 'EUR',
      spend: 100 + i, impressions: 10000 + 100 * i, clicks: 200 + 2 * i,
      website_sessions: 140 + 2 * i, view_item: 110 + i,
      add_to_cart: 24 + (i % 7), begin_checkout: 12 + (i % 5),
      purchases: metaPurchases, purchase_revenue: metaPurchases * (80 + 5 * (i % 4)),
    },
    {
      date, channel: 'google_ads', campaign_id: 'demo-google-01', currency: 'EUR',
      spend: 150 + 2 * i, impressions: 5000 + 100 * i, clicks: 150 + 3 * i,
      website_sessions: 120 + 2 * i, view_item: 100 + i,
      add_to_cart: 30 + (i % 7), begin_checkout: 18 + (i % 5),
      purchases: googlePurchases, purchase_revenue: googlePurchases * (90 + 5 * (i % 4)),
    },
  );
}

const expected = {
  spend: 8805, impressions: 537000, clicks: 12675,
  website_sessions: 9540, view_item: 7170, add_to_cart: 1790,
  begin_checkout: 1020, purchases: 450, purchase_revenue: 41925,
};
const totals = Object.fromEntries(Object.keys(expected).map((field) => [field, 0]));
const keys = new Set();
for (const row of rows) {
  const key = [row.date, row.channel, row.campaign_id, row.currency].join('|');
  if (keys.has(key)) throw new Error(`Duplicate generated fixture identity: ${key}`);
  keys.add(key);
  for (const field of Object.keys(expected)) {
    if (!Number.isFinite(row[field]) || row[field] < 0) {
      throw new Error(`Invalid generated fixture field: ${field}`);
    }
    totals[field] += row[field];
  }
}
if (rows.length !== 60 || keys.size !== 60) throw new Error('Expected exactly 60 unique generated records.');
for (const [field, value] of Object.entries(expected)) {
  if (totals[field] !== value) throw new Error(`Generated fixture total mismatch for ${field}: ${totals[field]} !== ${value}`);
}

return [{
  json: {
    metadata: {
      synthetic: true,
      schema_version: 'demo.v2',
      generated_at: new Date().toISOString(),
      row_count: 60,
    },
    rows,
  },
}];

const response = $json;
const expected = {
  spend: 8805, impressions: 537000, clicks: 12675,
  website_sessions: 9540, view_item: 7170, add_to_cart: 1790,
  begin_checkout: 1020, purchases: 450, purchase_revenue: 41925,
};
const failures = [];
if (response.synthetic !== true) failures.push('synthetic flag is not true');
if (response.schema_version !== 'demo.v2') failures.push('schema version is not demo.v2');
if (response.imported_record_count !== 60) failures.push('imported record count is not 60');
if (response.total_unique_row_count !== 60) failures.push('total unique row count is not 60');
if (!response.imported_at || !Number.isFinite(Date.parse(response.imported_at))) failures.push('import timestamp is missing or invalid');
for (const [field, value] of Object.entries(expected)) {
  if (!response.totals || response.totals[field] !== value) {
    failures.push(`${field} total does not equal ${value}`);
  }
}
if (failures.length > 0) throw new Error(`Neptun demo import verification failed: ${failures.join('; ')}`);

return [{
  json: {
    success: true,
    message: 'Neptun synthetic demo import verified: 60 unique rows and every baseline total matches.',
    imported_record_count: response.imported_record_count,
    total_unique_row_count: response.total_unique_row_count,
    imported_at: response.imported_at,
    totals: response.totals,
  },
}];
